// Think through your constraints before the interview
record LocationConstraint(
    boolean canRelocate,
    String relocateScope,        // within city, within state, anywhere in country
    String noticeNeeded,         // 1 month, 2-3 months, 6 months
    String reason                // family, lease, other commitments
) {}

record TravelConstraint(
    boolean canTravel,
    int maxTravelPercent,        // 10, 20, 50 percent of time
    int maxConsecutiveDays,      // 3 days, 1 week, 2 weeks
    String limitation            // family, health, other responsibilities
) {}

// Example: Assess your situation honestly
var myLocationFlexibility = new LocationConstraint(
    true,                        // I can relocate
    "within India",              // Scope: anywhere in India
    "2-3 months",                // Need time to settle affairs
    "current lease ends in 2 months"
);

var myTravelFlexibility = new TravelConstraint(
    true,                        // I can travel
    20,                          // Up to 20 percent travel is fine
    5,                           // Max 5 consecutive days away
    "family commitments on weekends"
);

// Your answer should reflect this honest assessment
var answer = String.format(
    "I can relocate %s with %s notice. I'm open to %d%% travel with trips up to %d days.",
    myLocationFlexibility.relocateScope,
    myLocationFlexibility.noticeNeeded,
    myTravelFlexibility.maxTravelPercent,
    myTravelFlexibility.maxConsecutiveDays
);
