// This is the kind of problem-solving that appealed to you
@Service
public class InventoryService {

    // Handling concurrent stock updates across multiple orders
    @Transactional(isolation = Isolation.SERIALIZABLE)
    public void reserveStock(Long productId, int quantity) {
        var product = productRepository.findById(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));

        if (product.stockLevel() < quantity) {
            throw new InsufficientStockException(productId, quantity);
        }

        // You found this kind of reasoning intellectually satisfying:
        // How do we prevent overselling when multiple users checkout simultaneously?
        // What isolation level ensures correctness without deadlocking?
        product.decrementStock(quantity);
        productRepository.save(product);

        // Publishing event for downstream systems
        eventPublisher.publish(new StockReservedEvent(productId, quantity));
    }

    // Optimizing query performance for high-traffic endpoints
    @Cacheable("product-stock")
    public StockLevel getStockLevel(Long productId) {
        // You enjoyed figuring out caching strategies to reduce DB load
        return productRepository.findStockLevel(productId);
    }
}
