// Year 3: You're designing subsystems and reviewing junior code
@Service
public class NotificationOrchestrator {
    // You proposed this architecture to handle multiple channels
    public void notifyCustomer(NotificationEvent event) {
        var strategies = notificationStrategyFactory.getStrategies(event.channels());
        strategies.forEach(strategy -> {
            try {
                strategy.send(event); // Delegates to EmailStrategy, SMSStrategy, etc.
            } catch (Exception e) {
                failureTracker.record(event, e);
            }
        });
    }
}

// Year 5: You're making architectural decisions for the entire notification domain
// You wrote the RFC for moving from synchronous to async event-driven notifications
@Component
public class NotificationEventListener {
    @EventListener
    public void handleOrderPlaced(OrderPlacedEvent event) {
        // You designed this decoupled architecture
        notificationQueue.publish(NotificationEvent.from(event));
    }
}
